import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Solve6 {

    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(System.out);
        new Solve6().calculate(out);
        out.flush();
        out.close();
    }

    public void calculate(PrintWriter out) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String inputLine = br.readLine();
        char[] chars = inputLine.toCharArray();
        int result = 0;
        int startIdx = 0;
        int endIdx = 0;
        while (startIdx < chars.length) {
            while (endIdx < chars.length && chars[endIdx] == chars[startIdx]) {
                endIdx++;
            }
            if ((endIdx - startIdx) % 2 == 0) {
                result++;
            }
            startIdx = endIdx;
        }
        out.println(result);
    }
}
